import Foundation
import XCTest
@testable import ShadowSigning

/// The iOS signer must match the node byte for byte. Vectors are generated by
/// the Python implementation: tests/fixtures/sig_v2_vectors.json.
final class SignatureV2VectorTests: XCTestCase {
    struct Vectors: Decodable {
        struct Case: Decodable {
            let name, method, path, query, body, canonical_query, signature: String
        }
        let secret, device_id, nonce: String
        let timestamp: Int
        let cases: [Case]
    }

    func testSharedVectors() throws {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("../../tests/fixtures/sig_v2_vectors.json").standardized
        let v = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
        XCTAssertFalse(v.cases.isEmpty)
        for c in v.cases {
            XCTAssertEqual(ShadowRequestSigner.canonicalQuery(c.query), c.canonical_query, c.name)
            let sig = ShadowRequestSigner.signature(
                secret: v.secret, method: c.method, path: c.path, query: c.query,
                body: Data(c.body.utf8), nonce: v.nonce, timestamp: String(v.timestamp), deviceId: v.device_id)
            XCTAssertEqual(sig, c.signature, c.name)
        }
    }

    func testHeadersSignTheQuery() throws {
        let identity = DeviceIdentity(deviceId: "dev_x", sharedSecret: "s", nodeFingerprint: "", publicKey: "",
                                      baseURL: URL(string: "http://127.0.0.1:8787")!)
        let url = URL(string: "http://127.0.0.1:8787/approvals?status=pending")!
        let h = ShadowRequestSigner().headers(identity: identity, method: "GET", url: url, body: Data())
        XCTAssertEqual(h["x-shadow-signature-version"], "2")
        let expected = ShadowRequestSigner.signature(
            secret: "s", method: "GET", path: "/approvals", query: "status=pending", body: Data(),
            nonce: h["x-shadow-nonce"]!, timestamp: h["x-shadow-timestamp"]!, deviceId: "dev_x")
        XCTAssertEqual(h["x-shadow-signature"], expected)
    }

    func testPublicKeyIs32RandomBytes() {
        let a = DevicePublicKey.generate(), b = DevicePublicKey.generate()
        XCTAssertEqual(a.count, 64)
        XCTAssertNotEqual(a, b)
    }
}
